pub fn tables() -> Vec<u32> {
    use optical_flow_solve::tables::{atables, stables};
    let mut v: Vec<u32> = Vec::new();
    v.extend_from_slice(&atables().log_head);
    v.extend_from_slice(&atables().log_tail);
    v.extend_from_slice(&atables().exp_table);
    v.extend_from_slice(&stables().rcp1);
    v.extend_from_slice(&stables().pair1);
    v.extend_from_slice(&stables().rcp2);
    v.extend_from_slice(&stables().pair2);
    v.extend_from_slice(&stables().rcp3);
    v.extend_from_slice(&stables().pair3);
    v.extend_from_slice(&stables().exp2);
    assert_eq!(v.len(), 385);
    v
}
